  ('3fb02683-0bf0-537a-b844-95cae8f956f2', null, (select id from public.skills where slug = 'write-g8-grammar-usage'), null, 'medium',
   $q$Read the sentence: "Students should wear goggles in the lab, and wash your hands before leaving." Which revision fixes the shift in mood?$q$, $q$[{"text":"Students should wear goggles in the lab, and you wash your hands before leaving.","is_correct":false,"misconception_token":"mood-shift"},{"text":"Students should wear goggles in the lab, and washing your hands before leaving.","is_correct":false,"misconception_token":"incomplete-verb"},{"text":"Wear goggles in the lab, and students should wash their hands before leaving.","is_correct":false,"misconception_token":"mood-shift"},{"text":"Students should wear goggles in the lab and should wash their hands before leaving.","is_correct":true}]$q$::jsonb, $q$Students should wear goggles in the lab and should wash their hands before leaving.$q$, $q$The sentence starts as a statement about what students should do, so the second verb must stay in that mood: "should wash their hands." The choice starting "Wear goggles in the lab" still mixes a command with a statement, just in the opposite order.$q$, 'draft', null)
